"use strict";const e=require("electron");e.contextBridge.exposeInMainWorld("electronAPI",{getBackendURL:()=>e.ipcRenderer.invoke("get-backend-url"),getAppVersion:()=>e.ipcRenderer.invoke("get-app-version"),isDev:()=>e.ipcRenderer.invoke("is-dev"),platform:process.platform,minimizeWindow:()=>e.ipcRenderer.send("window-minimize"),maximizeWindow:()=>e.ipcRenderer.send("window-maximize"),closeWindow:()=>e.ipcRenderer.send("window-close")});
